// ── TerpTalk strain catalog dataset (Slice C) ────────────────────────
// Research-driven curated catalog. Every row cites its evidence in
// docs/data/strain-research.md — a field is only populated when a source
// supports it; null means "not reliably reported", never a guess.
//
// Field policy (mirrors src/lib/strain-fields.ts — keep in sync):
//   type:           SATIVA | INDICA | HYBRID | RUDERALIS | AUTO_FLOWER | CBD | OTHER
//   genetics:       "Parent A x Parent B" when documented, else null
//   breeder:        canonical breeder name, or null (never "Unknown"/"Various")
//   description:    original TerpTalk writing — no copied breeder copy
//   effects:        subset of STRAIN_EFFECTS vocab (uppercase)
//   flavors:        subset of STRAIN_FLAVORS vocab (uppercase)
//   thcMin/thcMax:  published range; single published value goes on thcMax
//                   (renders "~N%"). null = not reliably reported. 0–45.
//   floweringWeeks: photoperiod flowering estimate 4–20; breeder range rounds
//                   to the upper week. null for autos ("days from seed" ≠
//                   flowering time) and unverifiable claims.
//   difficulty:     EASY | NORMAL | HARD | null
//
// The runner (seed-strains.cjs) validates this file against hard bounds
// before touching the database; tests cross-check against the real vocab.

